export default function StudentDetails({ student }) {
  const grade =
    student.marks >= 90 ? "A" :
    student.marks >= 75 ? "B" :
    student.marks >= 60 ? "C" :
    "D";

  return (
    <div className="card details-card">
      <h2>{student.name}</h2>

      <p><strong>Marks:</strong> {student.marks}</p>
      <p><strong>Grade:</strong> {grade}</p>
    </div>
  );
}
